"""Mechanical scope/preservation checks and duplicate candidate retrieval, no verdict creation."""
import json,hashlib,re,subprocess,collections,os
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[4];A=ROOT/'docs/content-audits/question-quality-wave-6/architecture/resume-2026-10-11-author100'
sha=lambda x:hashlib.sha256(x).hexdigest()
canon=lambda x:json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
receipt=json.loads((P/'receipt.json').read_text());cards=json.loads((ROOT/'src/content/topics/architecture.json').read_text())['questions'];byid={c['id']:c for c in cards}
fr=[x for n in ('batch02','pilot-arch-fix1') for x in json.loads((A/(n+'-freeze.json')).read_text())['cards']]
assert {x['questionId'] for x in fr}=={x['questionId'] for x in receipt['cards']}
assert all(sha(canon(byid[x['questionId']]))==x['cardCanonicalSha256'] for x in fr)
levels=collections.Counter(c['difficulty'] for c in cards);positions={d:[sum(c['difficulty']==d and c['correctIndex']==i for c in cards) for i in range(4)] for d in ('easy','medium','hard')}
assert levels=={'easy':40,'medium':40,'hard':20}; assert positions=={'easy':[10]*4,'medium':[10]*4,'hard':[5]*4}
sources={}
for row in receipt['cards']:
 for f in row['fields']:
  for proof in f['proofs']:
   p=(P/proof['rawCapture']).resolve();rel=str(p.relative_to(ROOT));assert sha(p.read_bytes())==proof['rawCaptureSha256']
   tracked=subprocess.run(['git','ls-files','--error-unmatch','--',rel],cwd=ROOT,capture_output=True).returncode==0
   sources[rel]={'sha256':proof['rawCaptureSha256'],'tracked':tracked}
assert all(v['tracked'] for v in sources.values()),'Source preservation needs owner commit'
patterns=[r'К[её]льн|Шартр|Ленотр|Версал|Химедзи|Боробуд|витраж|регулярн.*сад',r'Прамбанан|Потал|Персепол|Лалиб[еэ]л|Зимбабве|Бел[ыо][йг].*Красн|сух[ао].*кладк|скальн.*церк',r'Теотиуакан|Кито\b|кессон|Понте.Веккьо|лоджи|апсид|Храм.{0,2}Неб|Аюттха|Сукхота|Пасаргад|Кир.{0,12}(мавзол|гробниц)|арка\b|изогнут.*(про[её]м|конструкц)|Пирамид.{0,5}Солнца']
hits=[];cataloghash={}
for p in sorted((ROOT/'src/content/topics').glob('*.json')):
 body=p.read_bytes();cataloghash[p.name]=sha(body)
 for c in json.loads(body)['questions']:
  if any(re.search(pat,c['prompt']+' '+c['answers'][c['correctIndex']]['text'],re.I) for pat in patterns):
   hits.append({'topic':p.stem,'questionId':c['id'],'prompt':c['prompt'],'key':c['answers'][c['correctIndex']]['text'],'cardCanonicalSha256':sha(canon(c))})
(P/'duplicate-candidates.json').write_text(json.dumps({'method':'Case-insensitive retrieval on every current prompt and selected key. Candidates manually evaluated in editorialAnalysis; no semantic verdict generated by search.','patterns':patterns,'catalogFileHashesAtSearch':cataloghash,'candidates':hits},ensure_ascii=False,indent=2)+'\n')
result={'role':'independent','agentIdentity':os.environ['CODEX_THREAD_ID'],'baselineAtSessionStart':'3e76ab2fb537adf604ea1df8f29c814fb9b0c03c','headAtCheck':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'assignedCards':21,'readFields':126,'cardVerdicts':dict(collections.Counter(c['verdict'] for c in receipt['cards'])),'fieldVerdicts':dict(collections.Counter(f['verdict'] for c in receipt['cards'] for f in c['fields'])),'currentFrozenHashesMatch':True,'topicQuota':dict(levels),'topicKeyPositions':positions,'allRawSourcesTracked':True,'sources':sources,'rootCertification':False,'newCompletedCards':0,'qaScope':['verify-proof-format.py pilot5-receipt.json: literal/current card/original hash and passage roundtrip before expansion','verify-proof-format.py receipt.json: all21 current cards and126 fields; mechanical only','check_scope.py: exact assigned IDs/current frozen hashes/quota/positions/original preservation and global duplicate candidate retrieval'],'notRun':['full suite','npm run check','npm run qa','test:browser','build','deploy','release','archive'],'ownedOnly':'docs/content-audits/question-quality-wave-6/independent-pilot/resume-2026-10-11-architecture-batch02-fix1/'}
(P/'scope-check.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k not in ('sources','qaScope','notRun')},ensure_ascii=False))
